#!/usr/bin/env python3
"""Eight authorized primary-PDF transcription corrections; no global normalizer or prior-publication mutation."""
import datetime,hashlib,json,copy
from pathlib import Path
import pymupdf as fitz
from PIL import Image,ImageDraw
ROOT=Path(__file__).resolve().parents[3];OUT=Path(__file__).resolve().parent
def sha(value):return hashlib.sha256(value).hexdigest()
def main():
 proposals=json.loads((OUT/'proposals.json').read_text());frozen=json.loads((OUT/'baseline-records.json').read_text());baseline={i['id']:i for s in frozen['sources'] for i in s['records']};overrides=json.loads((OUT/'locator-overrides.json').read_text());rows=[];images=[]
 source=next(s['source'] for s in frozen['sources'] if s['source_id']=='br-bncc-2018');assert sha((ROOT/source['local_path']).read_bytes())==source['sha256']
 with fitz.open(ROOT/source['local_path']) as document:
  for proposal in proposals['records']:
   if proposal['strict_current_checker_passed']:continue
   item=baseline[proposal['id']];literal=proposal['raw_primary_excerpt'];primary=' '.join(literal.split());canonical=' '.join(item['text'].split());assert primary.replace('\u2013','-')==canonical;assert len(primary)==len(canonical)
   differences=[{'offset':index,'source':'\u2013','canonical':'-','context':primary[max(0,index-20):index+21]} for index,(a,b) in enumerate(zip(primary,canonical)) if a!=b];assert differences and all(primary[d['offset']]=='\u2013' and canonical[d['offset']]=='-' for d in differences)
   page=proposal['proposed_evidence'][1]['page'];actual=document[page-1];box=fitz.Rect(proposal['proposed_evidence'][1]['bbox']);glyphs=[{'unicode':c['c'],'bbox':list(c['bbox'])} for block in actual.get_text('rawdict')['blocks'] for line in block.get('lines',[]) for span in line['spans'] for c in span['chars'] if c['c']=='\u2013' and box.contains(fitz.Point((c['bbox'][0]+c['bbox'][2])/2,(c['bbox'][1]+c['bbox'][3])/2))];assert len(glyphs)==len(differences)
   region=box+(-3,-3,3,3);pix=actual.get_pixmap(matrix=fitz.Matrix(1.6,1.6),clip=region,alpha=False);image=Image.frombytes('RGB',[pix.width,pix.height],pix.samples);draw=ImageDraw.Draw(image)
   for glyph in glyphs:
    b=fitz.Rect(glyph['bbox']);draw.rectangle([(b.x0-region.x0)*1.6,(b.y0-region.y0)*1.6,(b.x1-region.x0)*1.6,(b.y1-region.y0)*1.6],outline='#b04c24',width=2)
   path=OUT/'renders'/('dash-'+item['code']+'.png');image.save(path);images.append((item['code'],image));rows.append({'id':item['id'],'code':item['code'],'source_id':item['source_id'],'artifact_sha256':source['sha256'],'page':page,'bbox':list(box),'canonical_text_sha256':sha(item['text'].encode()),'literal_primary_text':literal,'literal_primary_text_sha256':sha(literal.encode()),'only_whitespace_and_exact_declared_glyph_replacement':True,'replacement_policy':{'from':'\u2013','to':'-','source_codepoint':'U+2013','canonical_codepoint':'U+002D'},'differences':differences,'native_glyphs':glyphs,'review_render':str(path.relative_to(ROOT)),'review_render_sha256':sha(path.read_bytes()),'strict_original_checker_passed':False,'proposal_scope':'Frozen upstream text plus primary literal prove exactly 16 glyph differences. New canonical primary transcription is separately authorized for these eight records only; no generic normalization relaxation.'})
 assert len(rows)==8 and sum(len(row['differences']) for row in rows)==16
 stamp=datetime.datetime.now(datetime.timezone.utc).isoformat();proof={'actor_type':'automated','actor_id':'codex-independent-br-fidelity-auditor','generated_at':stamp,'denominator':8,'native_codepoint_differences':16,'all_other_characters_identical_after_existing_whitespace_collapse':True,'records':rows,'checker_modified_by_auditor':False,'upstream_dataset_text_modified':False,'new_primary_transcription_authorized':True,'ids_codes_prior_publications_modified':False};raw=(json.dumps(proof,ensure_ascii=False,indent=2)+'\n').encode();(OUT/'dash-typography-proof.json').write_bytes(raw)
 for row in rows:
  item=baseline[row['id']];old=next(p for p in proposals['records'] if p['id']==item['id']);evidence=copy.deepcopy(old['proposed_evidence']);evidence[1]['excerpt']=row['literal_primary_text'];evidence[1]['evidence_role']='primary_source_text';corrected=' '.join(row['literal_primary_text'].split());assert corrected.replace('–','-')==item['text'];correction={'method':'primary_pdf_dash_transcription_correction_v1','source_id':item['source_id'],'artifact_sha256':source['sha256'],'item_id':item['id'],'code':item['code'],'upstream_text_sha256':row['canonical_text_sha256'],'primary_source_text_sha256':row['literal_primary_text_sha256'],'corrected_text_sha256':sha(corrected.encode()),'differences':row['differences'],'native_glyphs':row['native_glyphs'],'proof_path':'docs/evidence/source-audit-br-fidelity/dash-typography-proof.json','proof_sha256':sha(raw),'decision_path':'docs/evidence/source-audit-br-fidelity/transcription-decision.json','decision_actor_type':'automated','decision_sha256':sha((OUT/'transcription-decision.json').read_bytes()),'scope':'New extraction/publication only; restore the primary EN DASH glyphs. Not an official curricular change. Previous publication/IDs remain immutable.'}
  overrides['sources'][item['source_id']]['records'][item['id']]={'expected_code':item['code'],'canonical_text_sha256':row['canonical_text_sha256'],'text':corrected,'upstream_text':item['text'],'primary_source_text':row['literal_primary_text'],'text_origin':'primary_pdf_transcription','primary_transcription_correction':correction,'canonical_text_policy':'Primary PDF transcript with whitespace normalized only. Original licensed dataset text is retained exactly in upstream_text. This is a documented extraction correction, not an official curriculum change.','technical_validation_status':'primary_code_and_literal_pdf_text_checked','editorial_note':'Correção identificada de extração: o texto canônico desta nova publicação preserva os travessões U+2013 visíveis no PDF primário. O texto anterior do dataset CC-BY permanece exato em upstream_text, com proveniência e diferenças de glifos registradas. Não houve alteração oficial do currículo, de código ou de ID.','evidence':evidence,'verification':{'actor_type':'automated','actor_id':'codex-independent-br-fidelity-auditor','method':'All 16 primary EN DASH glyphs confirmed by native rawdict/trace and rendered; original CC-BY text retained separately; all other characters identical after whitespace collapse','proof_path':'docs/evidence/source-audit-br-fidelity/dash-typography-proof.json','proof_sha256':sha(raw)},'requires_explicit_exact_glyph_policy_checker':False}
 overrides.update(proposed_records=394,approved_under_original_checker=386,requires_exact_glyph_policy=0,pending_records=[],transcription_corrections=8,expected_unchanged_licensed_texts=1713,global_normalizer_change=False,requires_new_extraction_revision='page-cell-v1.5.0',glyph_typography_proof_sha256=sha(raw),immutable_contract='IDs/codes/aliases and old publications immutable. Preserve 1713 licensed texts exactly. Only these eight root-authorized new transcription records change text to primary literal EN DASH; retain upstream_text exactly and all 16 glyph differences. Evidence-only changes for the other386. Original literal checker required; no mapping bypass.');(OUT/'locator-overrides.json').write_text(json.dumps(overrides,ensure_ascii=False,indent=2)+'\n')
 for offset in range(0,len(images),4):
  selected=images[offset:offset+4];sheet=Image.new('RGB',(900,sum(max(image.height+40,160) for _,image in selected)),'white');draw=ImageDraw.Draw(sheet);y=0
  for code,image in selected:draw.text((10,y+5),code+' : source EN DASH glyphs outlined',fill='black');sheet.paste(image,(10,y+30));y+=max(image.height+40,160)
  sheet.save(OUT/'renders'/f'dash-review-sheet-{offset//4+1}.png')
 print(json.dumps({'records':len(rows),'glyphs':16,'overlay_proposed_records':sum(len(s['records']) for s in overrides['sources'].values()),'original_checker_passed':386,'new_primary_transcription_corrections':8,'overrides_sha256':sha((OUT/'locator-overrides.json').read_bytes())}))
if __name__=='__main__':main()
